css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f5f7fa;color:#1b2939;font:16px/1.65 system-ui,sans-serif}header{background:#142a40;color:white;padding:28px 40px}header a{color:#c5e3f8}header h1{font-size:32px;margin:8px 0}header p{max-width:1000px;color:#c7d5e5;margin:5px 0}.layout{display:grid;grid-template-columns:225px minmax(0,1120px);gap:32px;max-width:1435px;margin:28px auto;padding:0 22px}aside{position:sticky;top:20px;align-self:start;border-left:3px solid #cbd7e3;padding:12px 15px;background:#edf2f6}aside a{display:block;font-size:13px;padding:5px 0;text-decoration:none;color:#425a70}article{min-width:0}section{background:white;padding:25px 30px;margin-bottom:22px;border:1px solid #dce4eb;border-radius:9px;scroll-margin-top:18px}h2{font-size:25px;margin:0 0 15px}h3{font-size:17px;margin:0 0 8px}p{margin:12px 0}a{color:#11698b}code{font:12px/1.6 ui-monospace,monospace;background:#eff3f6;padding:2px 4px;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;vertical-align:top;padding:10px 12px;border-bottom:1px solid #dfe6ed}th{background:#eef3f7;color:#365064}tbody tr:nth-child(even){background:#fafbfc}.table-scroll{overflow-x:auto}.callout{padding:16px 20px;border-left:4px solid #bf6c27;background:#fff6e9}.equation{display:flex;flex-wrap:wrap;gap:14px;align-items:center;padding:17px;background:#eef4f8;border-radius:6px}.unit{color:#587186;font-size:13px}select{max-width:100%;padding:8px;border:1px solid #b7c9d8;border-radius:5px;font:14px system-ui}.chart-card{padding:18px;border:1px solid #dfe6ed;margin-top:16px;border-radius:6px}svg{display:block;width:100%;height:auto}footer{color:#607387;margin:20px 0}li{margin:7px 0}'''
js='''const DATA=JSON.parse(document.getElementById('chart-data').textContent),sel=document.getElementById('run-select');function draw(){const p=DATA[sel.value].points;for(const [id,col,scale,threshold,unit,color] of [['ttft-chart',1,1000,4,'s','#166b8e'],['tpot-chart',2,1,40,'ms','#9b4c2d']]){const svg=document.getElementById(id),max=Math.max(threshold*1.3,...p.filter(x=>x[col]!=null).map(x=>x[col]/scale))*1.08,end=Math.max(...p.map(x=>x[0])),X=t=>50+825*t/end,Y=v=>215-190*v/max;let s='';for(let i=0;i<=4;i++){const v=max*i/4;s+=`<line x1="50" x2="875" y1="${Y(v)}" y2="${Y(v)}" stroke="#e1e8ee"/><text x="43" y="${Y(v)+4}" text-anchor="end" font-size="11" fill="#556b7d">${v.toFixed(1)}</text>`}for(let t=0;t<=end;t+=120)s+=`<text x="${X(t)}" y="239" text-anchor="middle" font-size="11" fill="#556b7d">${t}s</text>`;s+=`<line x1="50" x2="875" y1="${Y(threshold)}" y2="${Y(threshold)}" stroke="#b54032" stroke-dasharray="5 4"/><text x="870" y="${Y(threshold)-5}" text-anchor="end" font-size="11" fill="#b54032">${threshold} ${unit}</text>`;s+=`<polyline fill="none" stroke="${color}" stroke-width="2" points="${p.filter(x=>x[col]!=null).map(x=>X(x[0])+','+Y(x[col]/scale)).join(' ')}"/>`;svg.innerHTML=s;svg.onmousemove=e=>{const rect=svg.getBoundingClientRect(),t=((e.clientX-rect.left)/rect.width*900-50)/825*end,q=p.reduce((a,b)=>Math.abs(b[0]-t)<Math.abs(a[0]-t)?b:a);document.getElementById('point-readout').textContent=`${sel.value} · elapsed ${q[0]} s · TTFT p50 ${q[1]==null?'N/A':(q[1]/1000).toFixed(3)+' s'} · TPOT p99 ${q[2]==null?'N/A':q[2].toFixed(2)+' ms'}`}}}sel.onchange=draw;draw();'''
